        ("AIMEE_DB2_EVENT_EMBEDDING_REFUSALS", "AIMEE_DB2_EVENT_LIFECYCLE"),
        ("AIMEE_DB2_STAGE_EMBEDDING_REFUSALS", "AIMEE_DB2_FAMILY_LIFECYCLE"),
